// lib/collection/src/operations/types.rs:1468-1473
#[derive(Debug, Deserialize, Serialize, JsonSchema, Anonymize, Clone, PartialEq, Hash, Eq)]
#[serde(rename_all = "snake_case", untagged)]
pub enum VectorsConfig {
    Single(VectorParams),
    Multi(BTreeMap<VectorNameBuf, VectorParams>),
}

// lib/collection/src/operations/types.rs:1311-1320
#[derive(Default, Debug, Deserialize, Serialize, JsonSchema, Anonymize, Eq, PartialEq, Copy, Clone, Hash)]
#[serde(rename_all = "snake_case")]
pub enum Datatype {
    #[default]
    Float32,
    Uint8,
    Float16,
}

// lib/collection/src/operations/types.rs:1361-1371 (VectorParams)
#[serde(default, skip_serializing_if = "Option::is_none")]
/// Defines which datatype should be used to represent vectors in the storage.
pub datatype: Option<Datatype>,

